<template>
  <div class="recharge-panel-container h-full">
    <div class="flex h-full flex-col">
      <h2 class="mb-2 text-2xl font-bold">{{ $t('recharge.title') }}</h2>
      <Divider class="mb-3" />

      <!-- 加载状态 -->
      <div v-if="loading" class="flex items-center justify-center py-8">
        <i class="pi pi-spin pi-spinner text-2xl text-muted" />
      </div>

      <!-- 未登录状态 -->
      <div v-else-if="!isLoggedIn" class="flex flex-col items-center gap-4 py-8">
        <i class="pi pi-lock text-4xl text-muted" />
        <p class="text-muted">{{ $t('recharge.pleaseLogin') }}</p>
        <Button @click="handleLogin">
          <i class="pi pi-sign-in" />
          {{ $t('login.login') }}
        </Button>
      </div>

      <!-- 已登录状态 -->
      <div v-else class="flex flex-1 flex-col">
        <!-- 当前余额 -->
        <div class="mb-6 rounded-lg border border-border-default bg-surface p-4">
          <div class="mb-1 text-sm text-muted">{{ $t('recharge.currentBalance') }}</div>
          <div class="text-3xl font-bold text-primary">
            {{ Math.floor(currentBalance) }}
            <span class="ml-1 text-sm font-normal text-muted">{{ $t('recharge.pointsUnit') }}</span>
          </div>
        </div>

        <!-- 选择充值金额 -->
        <div class="mb-6">
          <h3 class="mb-3 text-sm font-medium text-base-foreground">
            {{ $t('recharge.selectAmount') }}
          </h3>
          <div class="grid grid-cols-3 gap-3">
            <div
              v-for="preset in PRESET_AMOUNTS"
              :key="preset.amount"
              class="cursor-pointer rounded-lg border-2 p-4 text-center transition-all"
              :class="
                selectedAmount === preset.amount
                  ? 'border-primary bg-primary/5'
                  : 'border-border-default hover:border-primary/50'
              "
              @click="handleSelectAmount(preset.amount)"
            >
              <div class="text-lg font-bold text-base-foreground">
                ¥ {{ preset.amount }}
              </div>
              <div class="mt-1 text-xs text-muted">
                {{ preset.points }} {{ $t('recharge.pointsUnit') }}
              </div>
            </div>
          </div>
        </div>

        <!-- 选择支付方式 -->
        <div class="mb-6">
          <h3 class="mb-3 text-sm font-medium text-base-foreground">
            {{ $t('recharge.selectPayment') }}
          </h3>
          <div class="flex gap-3">
            <div
              class="flex flex-1 cursor-pointer items-center gap-3 rounded-lg border-2 p-4 transition-all"
              :class="
                selectedPayment === 'wechat'
                  ? 'border-green-500 bg-green-500/5'
                  : 'border-border-default hover:border-green-500/50'
              "
              @click="selectedPayment = 'wechat'"
            >
              <svg class="h-6 w-6" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
                <path d="M9.5 4C5.36 4 2 6.69 2 10C2 11.89 3.08 13.56 4.78 14.66L4 17L6.81 15.5C7.64 15.8 8.55 16 9.5 16C9.67 16 9.83 16 10 15.99C9.69 15.39 9.5 14.72 9.5 14C9.5 10.69 12.47 8 16.15 8C16.38 8 16.61 8.01 16.84 8.04C16.04 5.69 13.04 4 9.5 4ZM7 9C6.45 9 6 8.55 6 8C6 7.45 6.45 7 7 7C7.55 7 8 7.45 8 8C8 8.55 7.55 9 7 9ZM12 9C11.45 9 11 8.55 11 8C11 7.45 11.45 7 12 7C12.55 7 13 7.45 13 8C13 8.55 12.55 9 12 9Z" fill="#07C160"/>
                <path d="M22 14C22 11.24 19.31 9 16 9C12.69 9 10 11.24 10 14C10 16.76 12.69 19 16 19C16.67 19 17.31 18.92 17.91 18.75L20 20L19.38 17.81C20.95 16.89 22 15.55 22 14ZM14 13C13.45 13 13 12.55 13 12C13 11.45 13.45 11 14 11C14.55 11 15 11.45 15 12C15 12.55 14.55 13 14 13ZM18 13C17.45 13 17 12.55 17 12C17 11.45 17.45 11 18 11C18.55 11 19 11.45 19 12C19 12.55 18.55 13 18 13Z" fill="#07C160"/>
              </svg>
              <span class="text-sm font-medium text-base-foreground">
                {{ $t('recharge.wechat') }}
              </span>
            </div>
            <div
              class="flex flex-1 cursor-pointer items-center gap-3 rounded-lg border-2 p-4 transition-all"
              :class="
                selectedPayment === 'alipay'
                  ? 'border-blue-500 bg-blue-500/5'
                  : 'border-border-default hover:border-blue-500/50'
              "
              @click="selectedPayment = 'alipay'"
            >
              <svg class="h-6 w-6" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
                <path d="M12 2C6.48 2 2 6.48 2 12C2 17.52 6.48 22 12 22C17.52 22 22 17.52 22 12C22 6.48 17.52 2 12 2ZM12.36 15.83C12.36 15.83 12.28 15.87 12.16 15.87C12.04 15.87 11.96 15.83 11.96 15.83L7.04 12.65C6.88 12.55 6.88 12.31 7.04 12.21L11.96 9.03C11.96 9.03 12.04 8.99 12.16 8.99C12.28 8.99 12.36 9.03 12.36 9.03L17.28 12.21C17.44 12.31 17.44 12.55 17.28 12.65L12.36 15.83Z" fill="#1677FF"/>
                <path d="M12.36 18.17C12.36 18.17 12.28 18.21 12.16 18.21C12.04 18.21 11.96 18.17 11.96 18.17L7.04 14.99C6.88 14.89 6.88 14.65 7.04 14.55L11.96 11.37C11.96 11.37 12.04 11.33 12.16 11.33C12.28 11.33 12.36 11.37 12.36 11.37L17.28 14.55C17.44 14.65 17.44 14.89 17.28 14.99L12.36 18.17Z" fill="#1677FF" opacity="0.7"/>
              </svg>
              <span class="text-sm font-medium text-base-foreground">
                {{ $t('recharge.alipay') }}
              </span>
            </div>
          </div>
        </div>

        <!-- 充值按钮 -->
        <Button
          :disabled="!canRecharge || submitting"
          :loading="submitting"
          variant="primary"
          size="lg"
          class="h-12 w-full justify-center text-base"
          @click="handleRecharge"
        >
          {{ $t('recharge.payNow') }} ¥ {{ selectedAmount }}
        </Button>

        <!-- 支付提示 -->
        <p class="mt-3 text-center text-xs text-muted">
          {{ $t('recharge.paymentHint') }}
        </p>
      </div>
    </div>
  </div>
</template>

<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { useI18n } from 'vue-i18n'
import { useToast } from 'primevue/usetoast'
import Divider from 'primevue/divider'

import Button from '@/components/ui/button/Button.vue'
import { pointsApi } from '@/scripts/pointsApi'
import { usePointsStats } from '@/composables/points/usePointsStats'
import { useUserStore } from '@/stores/userStore'
import { api } from '@/scripts/api'

const { t } = useI18n()
const toast = useToast()
const userStore = useUserStore()
const { stats, fetchStats } = usePointsStats()

const isLoggedIn = ref(false)
const loading = ref(true)
const selectedAmount = ref(9.9)
const selectedPayment = ref<'wechat' | 'alipay'>('wechat')
const submitting = ref(false)

const PRESET_AMOUNTS = [
  { amount: 9.9, points: 1000 },
  { amount: 19.9, points: 3000 },
  { amount: 49.9, points: 10000 },
  { amount: 99.9, points: 25000 },
  { amount: 199, points: 50000 },
  { amount: 1, points: 100 }
]

const currentBalance = computed(() => stats.value.balance)

const canRecharge = computed(
  () => selectedAmount.value > 0 && selectedPayment.value
)

function handleSelectAmount(amount: number) {
  selectedAmount.value = amount
}

async function checkLoginStatus() {
  loading.value = true
  try {
    const config = await api.getUserConfig()
    if (config?.users?.length) {
      isLoggedIn.value = true
      if (!userStore.currentUserId) {
        userStore.login({
          userId: config.users[0].userId,
          username: config.users[0].username
        })
      }
      await fetchStats()
    } else {
      isLoggedIn.value = false
    }
  } catch {
    isLoggedIn.value = false
  } finally {
    loading.value = false
  }
}

async function handleRecharge() {
  if (submitting.value || !canRecharge.value) return

  submitting.value = true
  try {
    const order = await pointsApi.createRechargeOrder(
      selectedAmount.value,
      selectedPayment.value
    )

    if (order.paymentUrl) {
      window.open(order.paymentUrl, '_blank')
    }

    toast.add({
      severity: 'info',
      summary: t('recharge.paymentTitle'),
      detail: t('recharge.paymentProcessing'),
      life: 5000
    })

    const result = await pollOrderStatus(order.orderId)
    if (result === 'paid') {
      toast.add({
        severity: 'success',
        summary: t('recharge.paymentSuccess'),
        detail: `+${order.points} ${t('recharge.pointsUnit')}`,
        life: 5000
      })
      await fetchStats()
    } else {
      toast.add({
        severity: 'warn',
        summary: t('recharge.paymentFailed'),
        detail: t('recharge.paymentTimeout'),
        life: 5000
      })
    }
  } catch (e: any) {
    toast.add({
      severity: 'error',
      summary: t('recharge.createOrderFailed'),
      detail: e.message || t('recharge.unknownError'),
      life: 5000
    })
  } finally {
    submitting.value = false
  }
}

async function pollOrderStatus(orderId: string): Promise<string> {
  const maxRetries = 60
  const interval = 3000

  for (let i = 0; i < maxRetries; i++) {
    try {
      const orderStatus = await pointsApi.getOrderStatus(orderId)
      if (orderStatus.status === 'paid') {
        return 'paid'
      }
    } catch {
      // ignore
    }
    await new Promise((resolve) => setTimeout(resolve, interval))
  }

  return 'timeout'
}

function handleLogin() {
  window.location.href = '/login'
}

onMounted(() => {
  void checkLoginStatus()
})
</script>
